#!/usr/bin/env Rscript
args <- commandArgs(trailingOnly=TRUE); val <- function(n,d=NULL) { x<-grep(paste0("^--",n,"="),args,value=TRUE); if(!length(x)) d else sub(paste0("^--",n,"="),"",x[[1]]) }
mode <- val("mode","validate"); root <- val("output",NULL); pkg <- normalizePath(val("pkg",getwd()),mustWork=TRUE)
if (!mode %in% c("validate","preflight") || is.null(root)) stop("require mode validate/preflight and --output",call.=FALSE)
root <- normalizePath(if(grepl("^/",root)) root else file.path(getwd(),root),mustWork=FALSE); script <- normalizePath(gsub("~+~", " ", sub("^--file=","",grep("^--file=",commandArgs(FALSE),value=TRUE)[[1]]), fixed = TRUE),mustWork=TRUE)
source(file.path(dirname(script),"g2f-pa-replication-fixture.R"),local=TRUE); hash <- function(x) unname(tools::md5sum(x))[[1L]]
check <- function(){ fx<-g2f_make_fixture(); g2f_validate_fixture(fx); o<-g2f_information_oracle(fx); stopifnot(all(o$survey_probability>0&o$survey_probability<1),all(is.finite(o$pa_one_visit_information_eta)),all(o$pa_information_ratio==2),all(is.finite(o$gbif_information_eta))); list(fx=fx,oracle=o) }
if(mode=="validate"){check();cat("G2F six-visit fixture/source-gate/oracle validation PASS (no fit)\n")} else { parent<-normalizePath(file.path(pkg,"dev","isdm-package-recovery","results"),mustWork=FALSE); if(!startsWith(root,paste0(parent,"/"))||grepl("g2c|g2d|g2e",basename(root),ignore.case=TRUE)||dir.exists(root)&&length(list.files(root,all.files=TRUE,no..=TRUE)))stop("G2f preflight root must be fresh and cannot reuse a retained G2c/G2d/G2e root",call.=FALSE); dir.create(root,recursive=TRUE,showWarnings=FALSE); z<-check(); base<-dirname(script); rec<-list(kind="G2F_PREFLIGHT",commit=system2("git",c("-C",shQuote(pkg),"rev-parse","HEAD"),stdout=TRUE)[[1]],fixture_md5=hash(file.path(base,"g2f-pa-replication-fixture.R")),runner_md5=hash(script),protocol_md5=hash(file.path(base,"2026-08-11-g2f-pa-replication-protocol.md")),decision_md5=hash(file.path(base,"2026-08-11-g2f-pa-replication-decision.md")),seed=g2f_seed); saveRDS(rec,file.path(root,"root-receipt.rds"));saveRDS(z$fx$truth,file.path(root,"truth.rds"));saveRDS(z$oracle,file.path(root,"information-oracle.rds")); fs<-file.path(root,c("root-receipt.rds","truth.rds","information-oracle.rds"));utils::write.csv(data.frame(path=basename(fs),md5=vapply(fs,hash,character(1))),file.path(root,"preflight-file-manifest.csv"),row.names=FALSE); stopifnot(identical(readRDS(file.path(root,"root-receipt.rds")),rec),identical(readRDS(file.path(root,"truth.rds")),z$fx$truth),identical(readRDS(file.path(root,"information-oracle.rds")),z$oracle));cat("G2F_PREFLIGHT_PASS (no fit)\n")}
